// Configuração da curadoria automática
// Edite as keywords do seu nicho e thresholds
const keywords = [
  'achadinhos de casa',
  'garrafa térmica',
  'skincare barato',
  'organizador de cozinha',
  'fone bluetooth custo benefício'
];

// Regras locais (espelham as do MineraAI, mas podem ser diferentes no n8n)
const rules = {
  min_viral_score: 40,
  min_views: 2000,
  platforms: ['youtube','tiktok','instagram'],
  limit: 10
};

return keywords.map(kw => ({ json: { query: kw, ...rules } }));

// Agrega resultados do lote
const results = $input.all().map(i => i.json);
const totalCriados = results.reduce((s, r) => s + (r.criados||0), 0);
const totalIgnorados = results.reduce((s, r) => s + (r.ignorados_duplicados||0), 0);
const totalBloqueados = results.reduce((s, r) => s + (r.bloqueados||0), 0);
return [{ json: { totalCriados, totalIgnorados, totalBloqueados, detalhes: results.map(r => `${r.query}: ${r.criados} novos`).join(' · ') } }];

// Prepara mensagem para Telegram/Slack/Discord opcional
const resumo = $('Resumo Curadoria').first().json;
const outliers = $input.first().json.outliers || [];
let msg = `✅ Curadoria automática MineraAI\nNovos: ${resumo.totalCriados} | Duplicados: ${resumo.totalIgnorados} | Bloqueados: ${resumo.totalBloqueados}\n${resumo.detalhes}`;
if (outliers.length) {
  msg += `\n\n🔥 Outliers ≥75: ${outliers.length}\n` + outliers.map(o => `• ${o.video.title.slice(0,60)} (${o.video.platform} ${o.curadoria.score_curadoria})`).join('\n');
}
return [{ json: { mensagem: msg, outliers_count: outliers.length, totalCriados: resumo.totalCriados } }];
